let architectureSelected=null, architectureCanPublish=false, architectureDirty=false, architecturePending=false, architectureJob=null, architectureGeneration=0;
const architectureCall=async(name,args={})=>(await api('/api/tool/'+name,args)).result;
function architectureMessage(text,error=false){$('arAdminStatus').textContent=text;$('arAdminStatus').className=error?'err-text':'hint';}
function architectureDraft(){const d=JSON.parse($('arAdminStructure').value);if(!d||Array.isArray(d)||typeof d!=='object')throw Error('Structure must be a JSON object');return {...d,title:$('arAdminTitle').value,summary:$('arAdminSummary').value,body:$('arAdminBody').value};}
function architectureReset(){architectureGeneration++;architectureSelected=null;architectureDirty=false;$('arAdminPreview').removeAttribute('src');$('arAdminId').value='';$('arAdminTitle').value='';$('arAdminSummary').value='';$('arAdminBody').value='';$('arAdminReason').value='';$('arAdminStructure').value=JSON.stringify({status:'active',tags:[],owners:[],evidence:[],nodes:[],relations:[],flows:[],views:[]},null,2);$('arAdminHistory').textContent='New shared document; first publication.';$('arAdminRevision').textContent='New document';}
function architectureCanLeave(){if(architecturePending){architectureMessage('Wait for the publication response before changing scope.',true);return false;}return !architectureDirty||confirm('Discard the unpublished architecture draft?');}
async function loadArchitectureAdmin(){const generation=++architectureGeneration;const r=await architectureCall('architecture_list',{limit:1000,include_archived:true});if(generation!==architectureGeneration)return;architectureCanPublish=r.canPublish;for(const id of ['arAdminPublish','arAdminNew','arAdminRefresh'])$(id).disabled=!r.canPublish;for(const id of ['arAdminId','arAdminTitle','arAdminSummary','arAdminBody','arAdminStructure','arAdminReason'])$(id).readOnly=!r.canPublish;$('arAdminPermissions').textContent=r.canPublish?'Global knowledge · Admin publication · Everyone can read':'Global knowledge · Read access · Admins publish';$('arAdminList').innerHTML=r.documents.map(d=>`<button data-architecture="${esc(d.id)}"><strong>${esc(d.title)}</strong><small>${esc(d.status)} · ${esc(d.author?.principalId)} · ${esc(d.revision.slice(0,12))}</small></button>`).join('')||'<p class="hint">No published architecture. Create a document with explicit entity IDs, evidence and named views.</p>';for(const b of $('arAdminList').querySelectorAll('button'))b.onclick=()=>architectureOpen(b.dataset.architecture).catch(e=>architectureMessage(e.message,true));if(!$('arAdminStructure').value)architectureReset();}
async function architectureOpen(id,force=false){if(!force&&!architectureCanLeave())return;const generation=++architectureGeneration,r=await architectureCall('architecture_get',{id,env:env()});if(generation!==architectureGeneration)return;architectureSelected=r;architectureDirty=false;$('arAdminId').value=r.id;$('arAdminTitle').value=r.document.title;$('arAdminSummary').value=r.document.summary;$('arAdminBody').value=r.document.body;const{title,summary,body,...structure}=r.document;$('arAdminStructure').value=JSON.stringify(structure,null,2);$('arAdminReason').value='';$('arAdminRevision').textContent='Revision '+r.revision+' · '+r.author.principalId+' · '+r.at;$('arAdminHistory').textContent=JSON.stringify(r.history,null,2);$('arAdminPreview').src=r.view+'?embed=1';architectureMessage('Read published revision. Edits remain a draft until an admin publishes.');}
async function architecturePublish(){if(architecturePending)return;try{const document=architectureDraft(),id=$('arAdminId').value.trim();architecturePending=true;$('arAdminPublish').disabled=true;const generation=architectureGeneration,r=await architectureCall('architecture_save',{id,expected_revision:architectureSelected?.id===id?architectureSelected.revision:null,reason:$('arAdminReason').value,document});if(generation!==architectureGeneration)return;architectureDirty=false;await architectureOpen(r.id,true);await loadArchitectureAdmin();architectureMessage('Published globally with immutable history.');}catch(e){architectureMessage(e.message+' Your draft is preserved.',true);}finally{architecturePending=false;$('arAdminPublish').disabled=!architectureCanPublish;}}
async function architectureObserve(){try{const r=await architectureCall('architecture_refresh',architectureJob?{job:architectureJob,env:env(),waitMs:0}:{env:env(),waitMs:0});architectureJob=typeof r.job==='string'?r.job:r.job?.id||r.id||architectureJob;$('arAdminJob').textContent=JSON.stringify(r,null,2);const active=['queued','running','starting'].includes(r.state||r.status||r.job?.state);$('arAdminCancel').hidden=!active;$('arAdminPoll').hidden=!active;$('arAdminRefresh').disabled=active||!architectureCanPublish;if(!active)architectureJob=null;}catch(e){architectureMessage(e.message,true);}}
function architectureAdminInit(){if(!$('arAdminPublish'))return;$('arAdminPublish').onclick=architecturePublish;$('arAdminNew').onclick=()=>{if(architectureCanLeave())architectureReset();};$('arAdminReload').onclick=()=>loadArchitectureAdmin().catch(e=>architectureMessage(e.message,true));$('arAdminEstate').onclick=async()=>{try{const r=await architectureCall('architecture_view',{env:env(),type:'landscape'});$('arAdminPreview').src=r.view+'?embed=1';}catch(e){architectureMessage(e.message,true);}};$('arAdminRefresh').onclick=$('arAdminPoll').onclick=architectureObserve;$('arAdminCancel').onclick=async()=>{try{await architectureCall('job_cancel',{job:architectureJob});await architectureObserve();}catch(e){architectureMessage(e.message,true);}};for(const id of ['arAdminId','arAdminTitle','arAdminSummary','arAdminBody','arAdminStructure','arAdminReason'])$(id).addEventListener('input',()=>architectureDirty=true);addEventListener('beforeunload',e=>{if(architectureDirty){e.preventDefault();e.returnValue='';}});}
document.addEventListener('DOMContentLoaded',architectureAdminInit);
